/**
 * Slop Guard extension for pi.
 *
 * Pi does not ship with built-in MCP support, so this extension wraps the
 * `slop-guard` CLI directly while preserving the upstream MCP tool names.
 */

import type { AgentToolResult, ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import type { AssistantMessage } from "@earendil-works/pi-ai";
import { Type } from "typebox";
import { constants as fileConstants } from "node:fs";
import { access, mkdtemp, readFile, rm, stat, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { basename, extname, join, resolve } from "node:path";

import {
	applySoftwareMetaphorPolicy,
	type SlopReport as SlopGuardReport,
	type SlopViolation,
} from "./software-metaphor-policy.ts";
import { createSteResponseEnforcer, STE_CHECK_FAILURE_NOTICE } from "./ste-response-enforcement.ts";
import { analyzeSteText, type SteReport } from "./ste-policy.ts";

const CONFIG_ENVIRONMENT_NAME = "PI_SLOP_GUARD_CONFIG";
